"""SQLAlchemy models for security alerts and evidence linkage."""

import uuid
from datetime import datetime, timezone
from sqlalchemy import String, Integer, SmallInteger, Float, Text, DateTime, ForeignKey, Index, CheckConstraint, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.db.base import Base, UUID_TYPE, JSONB_TYPE


class AlertModel(Base):
    """Explainable security alert generated by detection or correlation engines."""
    
    __tablename__ = "alerts"
    
    id: Mapped[uuid.UUID] = mapped_column(UUID_TYPE, primary_key=True, default=uuid.uuid4)
    alert_id: Mapped[uuid.UUID] = mapped_column(UUID_TYPE, unique=True, nullable=False, index=True)
    schema_version: Mapped[str] = mapped_column(String(16), nullable=False, default="1.0")
    detection_rule_id: Mapped[str] = mapped_column(
        String(64), ForeignKey("detection_rules.rule_id", ondelete="RESTRICT"), nullable=False, index=True
    )
    detection_rule_version: Mapped[str] = mapped_column(String(16), nullable=False)
    title: Mapped[str] = mapped_column(String(128), nullable=False)
    summary: Mapped[str] = mapped_column(Text, nullable=False)
    severity: Mapped[str] = mapped_column(String(16), nullable=False, index=True)
    confidence: Mapped[int] = mapped_column(SmallInteger, nullable=False)
    assessment_status: Mapped[str] = mapped_column(String(32), nullable=False, default="NEW", index=True)
    evidence_strength: Mapped[str] = mapped_column(String(32), nullable=False)
    source_address: Mapped[str] = mapped_column(String(45), nullable=False, index=True)
    observed_source_id: Mapped[str] = mapped_column(String(64), nullable=False, index=True)
    decoy_id: Mapped[str] = mapped_column(String(64), ForeignKey("honeypots.decoy_id", ondelete="RESTRICT"), nullable=False, index=True)
    target_service: Mapped[str] = mapped_column(String(32), nullable=False)
    first_observed_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    last_observed_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    generated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False, index=True)
    updated_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    detection_explanation: Mapped[str] = mapped_column(Text, nullable=False)
    recommendations: Mapped[dict] = mapped_column(JSONB_TYPE, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)
    
    # Task P28: SOC Triage & Prioritization Extensions
    assigned_analyst: Mapped[str | None] = mapped_column(String(128), nullable=True, index=True)
    triage_decision: Mapped[str | None] = mapped_column(String(32), nullable=True, index=True)
    triage_justification: Mapped[str | None] = mapped_column(Text, nullable=True)
    priority_score: Mapped[float | None] = mapped_column(Float, nullable=True, index=True)
    priority_level: Mapped[str | None] = mapped_column(String(16), nullable=True, default="P3_MEDIUM", index=True)
    resolution_category: Mapped[str | None] = mapped_column(String(64), nullable=True)
    resolution_reason: Mapped[str | None] = mapped_column(Text, nullable=True)
    escalation_reason: Mapped[str | None] = mapped_column(Text, nullable=True)
    escalation_role: Mapped[str | None] = mapped_column(String(64), nullable=True)
    closure_reason: Mapped[str | None] = mapped_column(Text, nullable=True)

    __table_args__ = (
        CheckConstraint(
            "severity IN ('INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL')",
            name="ck_alerts_severity"
        ),
        CheckConstraint(
            "confidence >= 0 AND confidence <= 100",
            name="ck_alerts_confidence_range"
        ),
        CheckConstraint(
            "assessment_status IN ('NEW', 'ACKNOWLEDGED', 'INVESTIGATING', 'ESCALATED', 'RESOLVED', 'CLOSED')",
            name="ck_alerts_assessment_status"
        ),
        Index("idx_alerts_sev_status", "severity", "assessment_status"),
        Index("idx_alerts_priority", "priority_score", "generated_at"),
    )
    
    # Relationships
    detection_rule: Mapped["DetectionRuleModel"] = relationship("DetectionRuleModel", back_populates="alerts")
    honeypot: Mapped["HoneypotModel"] = relationship("HoneypotModel", back_populates="alerts")
    evidence_links: Mapped[list["AlertEvidenceModel"]] = relationship("AlertEvidenceModel", back_populates="alert", cascade="all, delete-orphan")
    audit_logs: Mapped[list["AlertAuditLogModel"]] = relationship(
        "AlertAuditLogModel", back_populates="alert", cascade="all, delete-orphan", order_by="AlertAuditLogModel.created_at.desc()"
    )
    notes: Mapped[list["AlertNoteModel"]] = relationship(
        "AlertNoteModel", back_populates="alert", cascade="all, delete-orphan", order_by="AlertNoteModel.created_at.asc()"
    )


class AlertEvidenceModel(Base):
    """Many-to-many junction linking supporting normalized events to alerts."""
    
    __tablename__ = "alert_evidence"
    
    id: Mapped[uuid.UUID] = mapped_column(UUID_TYPE, primary_key=True, default=uuid.uuid4)
    alert_id: Mapped[uuid.UUID] = mapped_column(
        UUID_TYPE, ForeignKey("alerts.alert_id", ondelete="CASCADE"), nullable=False, index=True
    )
    event_id: Mapped[uuid.UUID] = mapped_column(
        UUID_TYPE, ForeignKey("security_events.event_id", ondelete="RESTRICT"), nullable=False, index=True
    )
    evidence_role: Mapped[str] = mapped_column(String(64), nullable=False, default="TRIGGERING_OBSERVATION")
    evidence_summary: Mapped[str | None] = mapped_column(Text, nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False)
    
    __table_args__ = (
        UniqueConstraint("alert_id", "event_id", name="uq_alert_evidence_pair"),
    )
    
    # Relationships
    alert: Mapped[AlertModel] = relationship("AlertModel", back_populates="evidence_links")
    security_event: Mapped["SecurityEventModel"] = relationship("SecurityEventModel", back_populates="alert_evidence_links")


class AlertAuditLogModel(Base):
    """Immutable audit trail for all triage decisions, lifecycle transitions, and analyst actions."""
    
    __tablename__ = "alert_audit_logs"
    
    id: Mapped[uuid.UUID] = mapped_column(UUID_TYPE, primary_key=True, default=uuid.uuid4)
    alert_id: Mapped[uuid.UUID] = mapped_column(
        UUID_TYPE, ForeignKey("alerts.alert_id", ondelete="CASCADE"), nullable=False, index=True
    )
    action_type: Mapped[str] = mapped_column(String(64), nullable=False, index=True)
    analyst_id: Mapped[str] = mapped_column(String(128), nullable=False)
    previous_status: Mapped[str | None] = mapped_column(String(32), nullable=True)
    new_status: Mapped[str | None] = mapped_column(String(32), nullable=True)
    reason: Mapped[str | None] = mapped_column(Text, nullable=True)
    details: Mapped[dict] = mapped_column(JSONB_TYPE, nullable=False, default=dict)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False, index=True
    )
    
    # Relationships
    alert: Mapped[AlertModel] = relationship("AlertModel", back_populates="audit_logs")


class AlertNoteModel(Base):
    """Append-only analyst notes attached to alerts during triage and investigation."""
    
    __tablename__ = "alert_notes"
    
    id: Mapped[uuid.UUID] = mapped_column(UUID_TYPE, primary_key=True, default=uuid.uuid4)
    alert_id: Mapped[uuid.UUID] = mapped_column(
        UUID_TYPE, ForeignKey("alerts.alert_id", ondelete="CASCADE"), nullable=False, index=True
    )
    author_id: Mapped[str] = mapped_column(String(128), nullable=False)
    author_role: Mapped[str] = mapped_column(String(64), nullable=False, default="SOC_ANALYST")
    content: Mapped[str] = mapped_column(Text, nullable=False)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=lambda: datetime.now(timezone.utc), nullable=False, index=True
    )
    
    # Relationships
    alert: Mapped[AlertModel] = relationship("AlertModel", back_populates="notes")

